type Product = { id: string; name: string; priceCents: number };

interface Cache {
    get(key: string): Promise<string | null>;
    set(key: string, value: string, options: { EX: number }): Promise<unknown>;
    del(key: string): Promise<unknown>;
}

interface Database {
    product(id: string): Promise<Product | null>;
    updateProduct(id: string, priceCents: number): Promise<Product>;
}

function keyFor(id: string): string {
    return `product:${id}`;
}

export async function getProduct(cache: Cache, db: Database, id: string): Promise<Product | null> {
    // TODO: read through the cache with a TTL and coalesce misses
    return db.product(id);
}

export async function updatePrice(cache: Cache, db: Database, id: string, priceCents: number): Promise<Product> {
    // TODO: update the database and invalidate the cached copy
    return db.updateProduct(id, priceCents);
}

